## Phase 2: Core Models & Data Structures (Week 1)

### **Step 4: Create ProcessingSettings Model**

File: `BatchSportsCardCropper.Core/Models/ProcessingSettings.cs`

```csharp
using System;
using System.ComponentModel.DataAnnotations;

namespace BatchSportsCardCropper.Core.Models
{
    public class ProcessingSettings
    {
        // Aspect Ratio Settings
        [Range(0.1, 5.0)]
        public decimal AspectRatio { get; set; } = 2.5m / 3.5m; // Trading card standard

        // Output Format Settings
        [Range(1, 100)]
        public int JpegQuality { get; set; } = 95;

        public string OutputFormat { get; set; } = "JPEG";
        public string BackgroundColor { get; set; } = "White";

        // Upscaling Settings
        public bool EnableUpscaling { get; set; } = true;
        [Range(2, 4)]
        public int UpscalingScale { get; set; } = 4;

        // Descratching Settings
        public bool EnableDescratching { get; set; } = true;
        [Range(0.0f, 1.0f)]
        public float DescratchingStrength { get; set; } = 0.8f;
        public bool UseAdvancedMask { get; set; } = true;
        public bool ApplyPostSharpening { get; set; } = true;

        // Output Directory
        public string OutputDirectory { get; set; } = 
            System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Desktop), "ProcessedCards");

        // Performance Settings
        public bool UseGpuAcceleration { get; set; } = true;
        public int MaxConcurrentProcessing { get; set; } = 4;

        // Validation
        public bool Validate(out string errorMessage)
        {
            errorMessage = string.Empty;

            if (AspectRatio <= 0)
            {
                errorMessage = "Aspect ratio must be greater than 0";
                return false;
            }

            if (JpegQuality < 1 || JpegQuality > 100)
            {
                errorMessage = "JPEG quality must be between 1 and 100";
                return false;
            }

            if (!System.IO.Directory.Exists(OutputDirectory))
            {
                try
                {
                    System.IO.Directory.CreateDirectory(OutputDirectory);
                }
                catch
                {
                    errorMessage = $"Cannot create output directory: {OutputDirectory}";
                    return false;
                }
            }

            return true;
        }

        // Serialization
        public string ToJson()
        {
            return Newtonsoft.Json.JsonConvert.SerializeObject(this, Newtonsoft.Json.Formatting.Indented);
        }

        public static ProcessingSettings FromJson(string json)
        {
            return Newtonsoft.Json.JsonConvert.DeserializeObject<ProcessingSettings>(json) 
                ?? new ProcessingSettings();
        }
    }
}
```

