### **Step 6: Create BatchJob Model**

File: `BatchSportsCardCropper.Core/Models/BatchJob.cs`

```csharp
using System;
using System.Collections.ObjectModel;
using System.Linq;

namespace BatchSportsCardCropper.Core.Models
{
    public class BatchJob
    {
        public string Id { get; set; } = Guid.NewGuid().ToString();
        public string Name { get; set; }
        public DateTime CreatedAt { get; set; } = DateTime.Now;

        public ObservableCollection<CardImage> Cards { get; set; } 
            = new ObservableCollection<CardImage>();

        public ProcessingSettings Settings { get; set; } = new ProcessingSettings();

        public BatchJobStatus Status { get; set; } = BatchJobStatus.Pending;

        // Statistics
        public int TotalCards => Cards.Count;
        public int ProcessedCards => Cards.Count(c => c.Status == ProcessingStatus.Completed);
        public int FailedCards => Cards.Count(c => c.Status == ProcessingStatus.Failed);
        public long TotalProcessingTimeMs => 
            (long)Cards.Where(c => c.Status == ProcessingStatus.Completed)
                .Sum(c => c.ProcessingTimeMs);

        public double Progress => TotalCards > 0 
            ? (ProcessedCards + FailedCards) / (double)TotalCards * 100 
            : 0;
    }

    public enum BatchJobStatus
    {
        Pending,
        Processing,
        Completed,
        Cancelled,
        Failed
    }
}
```

### **Step 7: Create ProcessingProgress Model**

File: `BatchSportsCardCropper.Core/Models/ProcessingProgress.cs`

```csharp
using System;

namespace BatchSportsCardCropper.Core.Models
{
    public class ProcessingProgress
    {
        public int CurrentIndex { get; set; }
        public int TotalCards { get; set; }
        public string CurrentCardName { get; set; }
        public ProcessingStatus CurrentStatus { get; set; }
        public string Message { get; set; }
        public DateTime StartTime { get; set; }
        public DateTime? EstimatedCompletion { get; set; }

        public double ProgressPercentage => 
            TotalCards > 0 ? (CurrentIndex / (double)TotalCards) * 100 : 0;

        public TimeSpan ElapsedTime => DateTime.Now - StartTime;

        public TimeSpan? RemainingTime
        {
            get
            {
                if (EstimatedCompletion.HasValue)
                    return EstimatedCompletion.Value - DateTime.Now;
                return null;
            }
        }
    }
}
