## Phase 3: Configuration & Utilities (Week 1)

### **Step 8: Create ConfigurationManager**

File: `BatchSportsCardCropper.Core/Utilities/ConfigurationManager.cs`

```csharp
using BatchSportsCardCropper.Core.Models;
using System;
using System.IO;

namespace BatchSportsCardCropper.Core.Utilities
{
    public class ConfigurationManager
    {
        private readonly string _configDirectory;
        private readonly string _settingsFile;

        public ConfigurationManager()
        {
            _configDirectory = Path.Combine(
                Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),
                "BatchSportsCardCropper");

            _settingsFile = Path.Combine(_configDirectory, "settings.json");

            EnsureDirectoryExists();
        }

        public ProcessingSettings LoadSettings()
        {
            try
            {
                if (!File.Exists(_settingsFile))
                    return new ProcessingSettings();

                var json = File.ReadAllText(_settingsFile);
                return ProcessingSettings.FromJson(json);
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine($"Error loading settings: {ex.Message}");
                return new ProcessingSettings();
            }
        }

        public void SaveSettings(ProcessingSettings settings)
        {
            try
            {
                EnsureDirectoryExists();
                var json = settings.ToJson();
                File.WriteAllText(_settingsFile, json);
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine($"Error saving settings: {ex.Message}");
            }
        }

        private void EnsureDirectoryExists()
        {
            if (!Directory.Exists(_configDirectory))
                Directory.CreateDirectory(_configDirectory);
        }
    }
}
```

### **Step 9: Create LoggingSetup**

File: `BatchSportsCardCropper.Core/Utilities/LoggingSetup.cs`

```csharp
using NLog;
using NLog.Config;
using NLog.Targets;
using System;
using System.IO;

namespace BatchSportsCardCropper.Core.Utilities
{
    public static class LoggingSetup
    {
        public static void Configure()
        {
            var logDirectory = Path.Combine(
                Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),
                "BatchSportsCardCropper", "Logs");

            Directory.CreateDirectory(logDirectory);

            var config = new LoggingConfiguration();

            // File target
            var fileTarget = new FileTarget("file")
            {
                FileName = Path.Combine(logDirectory, "${shortdate}.log"),
                Layout = "[${longdate}] [${level:uppercase=true}] ${logger} - ${message}"
            };

            // Console target
            var consoleTarget = new ConsoleTarget("console")
            {
                Layout = "[${longdate}] [${level:uppercase=true}] ${message}"
            };

            config.AddTarget(fileTarget);
            config.AddTarget(consoleTarget);

            config.AddRule(LogLevel.Debug, LogLevel.Fatal, "file");
            config.AddRule(LogLevel.Info, LogLevel.Fatal, "console");

            LogManager.Configuration = config;
        }

        public static ILogger GetLogger(string name) => LogManager.GetCurrentClassLogger();
    }
}
```

