## Phase 4: Core Image Processing Service (Week 2)

### **Step 10: Create ImageProcessingService**

File: `BatchSportsCardCropper.Core/Services/ImageProcessingService.cs`

```csharp
using SixLabors.ImageSharp;
using SixLabors.ImageSharp.PixelFormats;
using SixLabors.ImageSharp.Processing;
using SixLabors.ImageSharp.Formats.Jpeg;
using BatchSportsCardCropper.Core.Models;
using System;
using System.Threading.Tasks;
using NLog;

namespace BatchSportsCardCropper.Core.Services
{
    public class ImageProcessingService
    {
        private static readonly ILogger Logger = LogManager.GetCurrentClassLogger();

        /// <summary>
        /// Load image from file path
        /// </summary>
        public async Task<Image<Rgb24>> LoadImageAsync(string filePath)
        {
            try
            {
                Logger.Info($"Loading image: {filePath}");
                return await Task.Run(() => Image.Load<Rgb24>(filePath));
            }
            catch (Exception ex)
            {
                Logger.Error($"Failed to load image: {ex.Message}");
                throw;
            }
        }

        /// <summary>
        /// Crop image to specified aspect ratio
        /// </summary>
        public Image<Rgb24> CropToAspectRatio(Image<Rgb24> image, decimal aspectRatio)
        {
            try
            {
                Logger.Debug($"Cropping to aspect ratio: {aspectRatio}");

                int newWidth, newHeight;
                double currentRatio = image.Width / (double)image.Height;
                double targetRatio = (double)aspectRatio;

                if (currentRatio > targetRatio)
                {
                    // Image is too wide, crop width
                    newHeight = image.Height;
                    newWidth = (int)(newHeight * targetRatio);
                }
                else
                {
                    // Image is too tall, crop height
                    newWidth = image.Width;
                    newHeight = (int)(newWidth / targetRatio);
                }

                // Center the crop
                int offsetX = (image.Width - newWidth) / 2;
                int offsetY = (image.Height - newHeight) / 2;

                var rect = new Rectangle(offsetX, offsetY, newWidth, newHeight);

                return image.Clone(ctx => ctx.Crop(rect));
            }
            catch (Exception ex)
            {
                Logger.Error($"Failed to crop image: {ex.Message}");
                throw;
            }
        }

        /// <summary>
        /// Add background color/border to image
        /// </summary>
        public Image<Rgb24> AddBackground(Image<Rgb24> image, string backgroundColor)
        {
            try
            {
                Logger.Debug($"Adding background color: {backgroundColor}");

                // For now, just return the image as-is
                // Background would typically be added during cropping
                return image.Clone();
            }
            catch (Exception ex)
            {
                Logger.Error($"Failed to add background: {ex.Message}");
                throw;
            }
        }

        /// <summary>
        /// Save image as JPEG with specified quality
        /// </summary>
        public async Task SaveAsJpegAsync(Image<Rgb24> image, string outputPath, int quality = 95)
        {
            try
            {
                Logger.Info($"Saving image to: {outputPath}");

                var encoder = new JpegEncoder
                {
                    Quality = quality
                };

                await image.SaveAsJpegAsync(outputPath, encoder);
                Logger.Info($"Successfully saved image");
            }
            catch (Exception ex)
            {
                Logger.Error($"Failed to save image: {ex.Message}");
                throw;
            }
        }

        /// <summary>
        /// Process a single card image with all enhancements
        /// </summary>
        public async Task<string> ProcessCardAsync(
            string inputPath,
            ProcessingSettings settings,
            Func<ProcessingProgress, Task> progressCallback = null)
        {
            var startTime = DateTime.Now;

            try
            {
                // Step 1: Load image
                var image = await LoadImageAsync(inputPath);

                // Step 2: Crop to aspect ratio
                image = CropToAspectRatio(image, settings.AspectRatio);

                // Step 3: Add background (if needed)
                image = AddBackground(image, settings.BackgroundColor);

                // Step 4: Save as JPEG
                string fileName = System.IO.Path.GetFileNameWithoutExtension(inputPath);
                string outputPath = System.IO.Path.Combine(
                    settings.OutputDirectory,
                    $"{fileName}_processed.jpg");

                await SaveAsJpegAsync(image, outputPath, settings.JpegQuality);

                image.Dispose();

                Logger.Info($"Processing completed in {(DateTime.Now - startTime).TotalSeconds:F2}s");
                return outputPath;
            }
            catch (Exception ex)
            {
                Logger.Error($"Error processing card: {ex.Message}");
                throw;
            }
        }
    }
}
```

