using BatchSportsCardCropper.Core.Models;
using BatchSportsCardCropper.Core.Services;
using BatchSportsCardCropper.Core.Utilities;
using System;
using System.Collections.ObjectModel;
using System.ComponentModel;
using System.Runtime.CompilerServices;
using System.Windows.Input;

namespace BatchSportsCardCropper.UI.ViewModels
{
    public class MainViewModel : INotifyPropertyChanged
    {
        private BatchJob _currentBatch;
        private ProcessingSettings _settings;
        private double _progressPercentage;
        private string _statusMessage;

        public ObservableCollection<CardImage> Cards { get; }
        public ProcessingSettings Settings
        {
            get => _settings;
            set
            {
                if (_settings != value)
                {
                    _settings = value;
                    OnPropertyChanged();
                }
            }
        }

        public double ProgressPercentage
        {
            get => _progressPercentage;
            set
            {
                if (_progressPercentage != value)
                {
                    _progressPercentage = value;
                    OnPropertyChanged();
                }
            }
        }

        public string StatusMessage
        {
            get => _statusMessage;
            set
            {
                if (_statusMessage != value)
                {
                    _statusMessage = value;
                    OnPropertyChanged();
                }
            }
        }

        // Commands
        public ICommand ProcessCommand { get; }
        public ICommand DownloadCommand { get; }
        public ICommand BrowseFilesCommand { get; }

        private readonly ConfigurationManager _configManager;
        private readonly ImageProcessingService _imageService;

        public MainViewModel()
        {
            Cards = new ObservableCollection<CardImage>();
            _configManager = new ConfigurationManager();
            _imageService = new ImageProcessingService();

            // Load saved settings
            Settings = _configManager.LoadSettings();

            // Initialize commands
            ProcessCommand = new RelayCommand(() => OnProcess(), () => Cards.Count > 0);
            DownloadCommand = new RelayCommand(() => OnDownload());
            BrowseFilesCommand = new RelayCommand(() => OnBrowseFiles());

            StatusMessage = "Ready to process cards";
        }

        private void OnProcess()
        {
            StatusMessage = "Processing cards...";
            ProgressPercentage = 0;
            // Implementation will be added in next steps
        }

        private void OnDownload()
        {
            // Implementation for downloading processed images
        }

        private void OnBrowseFiles()
        {
            // Implementation for file browsing
        }

        public event PropertyChangedEventHandler PropertyChanged;

        protected void OnPropertyChanged([CallerMemberName] string name = null)
        {
            PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(name));
        }
    }

    // Helper command class
    public class RelayCommand : ICommand
    {
        private readonly Action _execute;
        private readonly Func<bool> _canExecute;

        public RelayCommand(Action execute, Func<bool> canExecute = null)
        {
            _execute = execute ?? throw new ArgumentNullException(nameof(execute));
            _canExecute = canExecute;
        }

        public event EventHandler CanExecuteChanged
        {
            add { CommandManager.RequerySuggested += value; }
            remove { CommandManager.RequerySuggested -= value; }
        }

        public bool CanExecute(object parameter) => _canExecute?.Invoke() ?? true;
        public void Execute(object parameter) => _execute();
    }
}
