## Phase 6: Batch Processing Service (Week 3)

### **Step 13: Create BatchProcessingService**

File: `BatchSportsCardCropper.Core/Services/BatchProcessingService.cs`

```csharp
using BatchSportsCardCropper.Core.Models;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using NLog;

namespace BatchSportsCardCropper.Core.Services
{
    public class BatchProcessingService
    {
        private static readonly ILogger Logger = LogManager.GetCurrentClassLogger();

        private readonly ImageProcessingService _imageService;
        private CancellationTokenSource _cancellationTokenSource;

        public event EventHandler<ProcessingProgress> ProgressChanged;
        public event EventHandler<Exception> ProcessingError;

        public BatchProcessingService()
        {
            _imageService = new ImageProcessingService();
        }

        public async Task ProcessBatchAsync(
            BatchJob batch,
            ProcessingSettings settings)
        {
            _cancellationTokenSource = new CancellationTokenSource();

            try
            {
                Logger.Info($"Starting batch processing: {batch.Name}");
                batch.Status = BatchJobStatus.Processing;

                var semaphore = new SemaphoreSlim(settings.MaxConcurrentProcessing);
                var tasks = new List<Task>();

                for (int i = 0; i < batch.Cards.Count; i++)
                {
                    if (_cancellationTokenSource.Token.IsCancellationRequested)
                        break;

                    var card = batch.Cards[i];
                    int index = i;

                    await semaphore.WaitAsync();

                    var task = ProcessCardAsync(card, settings, index, batch.Cards.Count, semaphore);
                    tasks.Add(task);
                }

                await Task.WhenAll(tasks);

                batch.Status = batch.Cards.Any(c => c.Status == ProcessingStatus.Failed)
                    ? BatchJobStatus.Failed
                    : BatchJobStatus.Completed;

                Logger.Info($"Batch processing completed: {batch.Name}");
            }
            catch (Exception ex)
            {
                Logger.Error($"Batch processing error: {ex.Message}");
                batch.Status = BatchJobStatus.Failed;
                ProcessingError?.Invoke(this, ex);
            }
        }

        private async Task ProcessCardAsync(
            CardImage card,
            ProcessingSettings settings,
            int index,
            int total,
            SemaphoreSlim semaphore)
        {
            var startTime = DateTime.Now;

            try
            {
                card.Status = ProcessingStatus.Processing;

                // Report progress
                var progress = new ProcessingProgress
                {
                    CurrentIndex = index + 1,
                    TotalCards = total,
                    CurrentCardName = System.IO.Path.GetFileName(card.InputPath),
                    CurrentStatus = ProcessingStatus.Processing,
                    Message = $"Processing: {System.IO.Path.GetFileName(card.InputPath)}"
                };
                ProgressChanged?.Invoke(this, progress);

                // Process the card
                card.OutputPath = await _imageService.ProcessCardAsync(
                    card.InputPath,
                    settings);

                card.Status = ProcessingStatus.Completed;
                card.ProcessedAt = DateTime.Now;
                card.ProcessingTimeMs = (long)(DateTime.Now - startTime).TotalMilliseconds;

                Logger.Info($"Card processed: {card.InputPath} ({card.ProcessingTimeMs}ms)");
            }
            catch (Exception ex)
            {
                card.Status = ProcessingStatus.Failed;
                card.ErrorMessage = ex.Message;
                Logger.Error($"Failed to process card: {ex.Message}");
            }
            finally
            {
                semaphore.Release();
            }
        }

        public void CancelProcessing()
        {
            _cancellationTokenSource?.Cancel();
            Logger.Info("Batch processing cancelled");
        }
    }
}
