using Microsoft.ML.OnnxRuntime;
using Microsoft.ML.OnnxRuntime.Tensors;
using NLog;
using System;
using System.Collections.Generic;

namespace BatchSportsCardCropper.AI.Inference
{
    public class OnnxInferenceEngine : IDisposable
    {
        private static readonly ILogger Logger = LogManager.GetCurrentClassLogger();

        private InferenceSession _session;
        private readonly string _modelPath;
        private readonly bool _useGpu;

        public OnnxInferenceEngine(string modelPath, bool useGpu = true)
        {
            _modelPath = modelPath;
            _useGpu = useGpu;
            InitializeSession();
        }

        private void InitializeSession()
        {
            try
            {
                var options = new SessionOptions();
                options.GraphOptimizationLevel = GraphOptimizationLevel.ORT_ENABLE_ALL;

                if (_useGpu)
                {
                    try
                    {
                        options.AppendExecutionProvider_CUDA();
                        Logger.Info("CUDA acceleration enabled");
                    }
                    catch
                    {
                        Logger.Warn("CUDA not available, using CPU");
                        options.AppendExecutionProvider_CPU();
                    }
                }
                else
                {
                    options.AppendExecutionProvider_CPU();
                }

                _session = new InferenceSession(_modelPath, options);
                Logger.Info($"ONNX model loaded: {_modelPath}");
            }
            catch (Exception ex)
            {
                Logger.Error($"Failed to initialize ONNX session: {ex.Message}");
                throw;
            }
        }

        public IDisposableReadOnlyCollection<DisposableNamedOnnxValue> Run(
            List<NamedOnnxValue> inputs)
        {
            try
            {
                return _session.Run(inputs);
            }
            catch (Exception ex)
            {
                Logger.Error($"ONNX inference error: {ex.Message}");
                throw;
            }
        }

        public void Dispose()
        {
            _session?.Dispose();
        }
    }
}
