using BatchSportsCardCropper.AI.Inference;
using Microsoft.ML.OnnxRuntime.Tensors;
using SixLabors.ImageSharp;
using SixLabors.ImageSharp.PixelFormats;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using NLog;

namespace BatchSportsCardCropper.Core.Services
{
    public class UpscalingService : IDisposable
    {
        private static readonly ILogger Logger = LogManager.GetCurrentClassLogger();

        private OnnxInferenceEngine _engine;
        private const int UPSCALE_FACTOR = 4;

        public UpscalingService(string modelPath, bool useGpu = true)
        {
            try
            {
                _engine = new OnnxInferenceEngine(modelPath, useGpu);
            }
            catch (Exception ex)
            {
                Logger.Error($"Failed to initialize upscaling service: {ex.Message}");
                throw;
            }
        }

        public async Task<Image<Rgb24>> UpscaleAsync(Image<Rgb24> inputImage)
        {
            return await Task.Run(() => Upscale(inputImage));
        }

        public Image<Rgb24> Upscale(Image<Rgb24> inputImage)
        {
            try
            {
                Logger.Debug($"Upscaling image: {inputImage.Width}x{inputImage.Height}");

                // Prepare input tensor
                var inputTensor = ImageToTensor(inputImage);

                // Run inference
                var inputs = new List<NamedOnnxValue>
                {
                    NamedOnnxValue.CreateFromTensor("input", inputTensor)
                };

                using (var results = _engine.Run(inputs))
                {
                    var outputTensor = results.First().AsTensor<float>();
                    var upscaledImage = TensorToImage(outputTensor);

                    Logger.Debug($"Upscaling completed: {upscaledImage.Width}x{upscaledImage.Height}");
                    return upscaledImage;
                }
            }
            catch (Exception ex)
            {
                Logger.Error($"Upscaling error: {ex.Message}");
                throw;
            }
        }

        private DenseTensor<float> ImageToTensor(Image<Rgb24> image)
        {
            var tensor = new DenseTensor<float>(
                new[] { 1, 3, image.Height, image.Width });

            image.ProcessPixelRows(accessor =>
            {
                for (int y = 0; y < image.Height; y++)
                {
                    var span = accessor.GetRowSpan(y);
                    for (int x = 0; x < image.Width; x++)
                    {
                        var pixel = span[x];
                        tensor[0, 0, y, x] = pixel.R / 255.0f;
                        tensor[0, 1, y, x] = pixel.G / 255.0f;
                        tensor[0, 2, y, x] = pixel.B / 255.0f;
                    }
                }
            });

            return tensor;
        }

        private Image<Rgb24> TensorToImage(Tensor<float> tensor)
        {
            var dims = tensor.Dimensions.ToArray();
            int height = dims[2];
            int width = dims[3];

            var image = new Image<Rgb24>(width, height);

            image.ProcessPixelRows(accessor =>
            {
                for (int y = 0; y < height; y++)
                {
                    var span = accessor.GetRowSpan(y);
                    for (int x = 0; x < width; x++)
                    {
                        byte r = (byte)Math.Clamp(tensor[0, 0, y, x] * 255, 0, 255);
                        byte g = (byte)Math.Clamp(tensor[0, 1, y, x] * 255, 0, 255);
                        byte b = (byte)Math.Clamp(tensor[0, 2, y, x] * 255, 0, 255);

                        span[x] = new Rgb24(r, g, b);
                    }
                }
            });

            return image;
        }

        public void Dispose()
        {
            _engine?.Dispose();
        }
    }
}
