using System;
using System.Runtime.InteropServices;
using System.Windows.Interop;
using NLog;

namespace BatchSportsCardCropper.Core.Utilities
{
    public class KeyboardShortcutManager
    {
        private static readonly ILogger Logger = LogManager.GetCurrentClassLogger();

        [DllImport("user32.dll")]
        private static extern bool RegisterHotKey(
            IntPtr hWnd, int id, uint fsModifiers, uint vk);

        [DllImport("user32.dll")]
        private static extern bool UnregisterHotKey(IntPtr hWnd, int id);

        private const uint MOD_CONTROL = 0x0002;
        private const uint VK_P = 0x50;
        private const uint VK_S = 0x53;

        private IntPtr _windowHandle;

        public event Action ProcessRequested;
        public event Action DownloadRequested;

        public KeyboardShortcutManager(IntPtr windowHandle)
        {
            _windowHandle = windowHandle;
            RegisterShortcuts();
        }

        private void RegisterShortcuts()
        {
            // Register Ctrl+P for Process
            if (RegisterHotKey(_windowHandle, 1, MOD_CONTROL, VK_P))
                Logger.Info("Ctrl+P shortcut registered");
            else
                Logger.Warn("Failed to register Ctrl+P");

            // Register Ctrl+S for Download
            if (RegisterHotKey(_windowHandle, 2, MOD_CONTROL, VK_S))
                Logger.Info("Ctrl+S shortcut registered");
            else
                Logger.Warn("Failed to register Ctrl+S");
        }

        public void HandleHotKey(int hotKeyId)
        {
            switch (hotKeyId)
            {
                case 1:
                    Logger.Debug("Ctrl+P pressed");
                    ProcessRequested?.Invoke();
                    break;
                case 2:
                    Logger.Debug("Ctrl+S pressed");
                    DownloadRequested?.Invoke();
                    break;
            }
        }

        public void Unregister()
        {
            UnregisterHotKey(_windowHandle, 1);
            UnregisterHotKey(_windowHandle, 2);
        }
    }
}
