import React, { useState } from 'react';
import { Sparkles, Loader2, Download, Image as ImageIcon, AlertCircle } from 'lucide-react';
import { generateCardImage } from '../services/geminiService';
import { ImageSize } from '../types';

const ImageGenerator: React.FC = () => {
  const [prompt, setPrompt] = useState('');
  const [size, setSize] = useState<ImageSize>(ImageSize.Size1K);
  const [generatedImage, setGeneratedImage] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleGenerate = async () => {
    if (!prompt.trim()) return;

    setIsLoading(true);
    setError(null);
    setGeneratedImage(null);

    try {
      const imageData = await generateCardImage(prompt, size);
      setGeneratedImage(imageData);
    } catch (err: any) {
      setError(err.message || 'Failed to generate image. Please check your API key.');
    } finally {
      setIsLoading(false);
    }
  };

  const selectKey = async () => {
    try {
        if(window.aistudio) {
            await window.aistudio.openSelectKey();
        }
    } catch(e) {
        console.error(e);
        setError("Could not open key selection dialog.");
    }
  }

  return (
    <div className="h-full bg-slate-50 p-6 md:p-12 overflow-y-auto">
      <div className="max-w-4xl mx-auto space-y-8">
        <div className="text-center space-y-3">
          <h2 className="text-3xl font-bold text-slate-900">AI Card Generator</h2>
          <p className="text-slate-500 max-w-lg mx-auto">
            Create unique sports card designs or fantasy players using the power of Nano Banana Pro.
          </p>
        </div>

        <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6 md:p-8">
           <div className="space-y-6">
             <div>
               <label className="block text-sm font-medium text-slate-700 mb-2">Prompt</label>
               <textarea
                 className="w-full h-32 bg-slate-50 border border-slate-300 rounded-xl p-4 focus:ring-2 focus:ring-blue-500 outline-none resize-none text-slate-800"
                 placeholder="Describe your card... e.g., 'A futuristic baseball card of a robot pitcher, holographic foil style, 1990s aesthetic'"
                 value={prompt}
                 onChange={(e) => setPrompt(e.target.value)}
               ></textarea>
             </div>

             <div className="grid md:grid-cols-2 gap-6">
                <div>
                   <label className="block text-sm font-medium text-slate-700 mb-2">Resolution</label>
                   <div className="grid grid-cols-3 gap-3">
                      {Object.values(ImageSize).map((s) => (
                        <button
                          key={s}
                          onClick={() => setSize(s)}
                          className={`py-2 px-3 rounded-lg text-sm font-medium border transition-all ${
                            size === s 
                             ? 'bg-blue-50 border-blue-500 text-blue-700' 
                             : 'bg-white border-slate-200 text-slate-600 hover:border-slate-300'
