                <div className="flex items-end">
                    <button
                        onClick={handleGenerate}
                        disabled={isLoading || !prompt.trim()}
                        className={`w-full py-2.5 rounded-xl font-medium text-white shadow-lg flex items-center justify-center gap-2 transition-all ${
                            isLoading || !prompt.trim()
                            ? 'bg-slate-400 cursor-not-allowed shadow-none'
                            : 'bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-700 hover:to-indigo-700 shadow-blue-200'
                        }`}
                    >
                        {isLoading ? <Loader2 className="animate-spin" size={20} /> : <Sparkles size={20} />}
                        {isLoading ? 'Generating...' : 'Generate Image'}
                    </button>
                </div>
             </div>

             {/* Key Selection Hint */}
             <div className="flex justify-end">
                <button onClick={selectKey} className="text-xs text-blue-500 underline hover:text-blue-700">
                    Change API Key (Required for Pro models)
                </button>
