import React, { useState, useRef, useCallback } from 'react';
import { Upload, X, Check, Loader2, Download, Settings, Play } from 'lucide-react';
import { CardImage, ProcessingStatus, ProcessingSettings } from '../types';
import JSZip from 'jszip';

const BatchCropper: React.FC = () => {
  const [cards, setCards] = useState<CardImage[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isDownloading, setIsDownloading] = useState(false);
  const [settings, setSettings] = useState<ProcessingSettings>({
    aspectRatio: 2.5 / 3.5,
    jpegQuality: 95,
    enableUpscaling: true,
    enableDescratching: true,
    upscalingScale: 4,
    backgroundColor: 'White'
  });

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileSelect = (event: React.ChangeEvent<HTMLInputElement>) => {
    if (event.target.files) {
      const newCards: CardImage[] = Array.from(event.target.files).map(file => ({
        id: Math.random().toString(36).substr(2, 9),
        file,
        previewUrl: URL.createObjectURL(file),
        status: ProcessingStatus.Pending,
        originalWidth: 0, // Would need image load to get actual dims
        originalHeight: 0
      }));
      setCards(prev => [...prev, ...newCards]);
    }
  };

  const removeCard = (id: string) => {
    setCards(prev => prev.filter(c => c.id !== id));
  };

  const processBatch = async () => {
    setIsProcessing(true);

    // Simulate processing sequence
    for (const card of cards) {
      if (card.status === ProcessingStatus.Completed) continue;

      setCards(prev => prev.map(c => c.id === card.id ? { ...c, status: ProcessingStatus.Processing } : c));

      // Simulate AI processing time (1-2 seconds per card)
      await new Promise(resolve => setTimeout(resolve, 1500));

      // In a real app, we would use a canvas to crop here and save to processedUrl
      // For demo, we just duplicate the previewUrl
      setCards(prev => prev.map(c => 
        c.id === card.id ? { ...c, status: ProcessingStatus.Completed, processedUrl: c.previewUrl } : c
      ));
    }

    setIsProcessing(false);
  };

  const handleDownloadBatch = async () => {
    const completedCards = cards.filter(c => c.status === ProcessingStatus.Completed && c.processedUrl);

    if (completedCards.length === 0) return;

    setIsDownloading(true);

    try {
      const zip = new JSZip();

      // Add files to zip
      const promises = completedCards.map(async (card) => {
        if (card.processedUrl) {
          try {
            const response = await fetch(card.processedUrl);
            const blob = await response.blob();
            // Create a clean filename
            const fileName = `processed-${card.file.name}`;
            zip.file(fileName, blob);
          } catch (err) {
            console.error(`Failed to fetch blob for ${card.id}`, err);
          }
        }
      });

      await Promise.all(promises);

      // Generate zip blob
      const content = await zip.generateAsync({ type: "blob" });

      // Trigger download
      const downloadUrl = URL.createObjectURL(content);
      const link = document.createElement('a');
      link.href = downloadUrl;
      link.download = `cardcrop-batch-${new Date().getTime()}.zip`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(downloadUrl);

    } catch (e) {
      console.error("Error generating zip:", e);
      alert("Failed to generate download bundle.");
    } finally {
      setIsDownloading(false);
    }
  };

  const completedCount = cards.filter(c => c.status === ProcessingStatus.Completed).length;
  const progress = cards.length > 0 ? (completedCount / cards.length) * 100 : 0;

  return (
    <div className="h-full flex flex-col">
      <header className="bg-white border-b border-slate-200 p-6 flex justify-between items-center sticky top-0 z-10">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Batch Processing</h2>
          <p className="text-slate-500 text-sm mt-1">Enhance, descratch, and crop your collection.</p>
        </div>

        <div className="flex gap-3">
            <button 
              onClick={() => fileInputRef.current?.click()}
              className="px-4 py-2 bg-white border border-slate-300 text-slate-700 rounded-lg hover:bg-slate-50 flex items-center gap-2 font-medium transition-colors"
            >
              <Upload size={18} />
              Add Images
            </button>
            <button 
              onClick={processBatch}
              disabled={isProcessing || cards.length === 0}
              className={`px-6 py-2 rounded-lg text-white font-medium flex items-center gap-2 transition-all shadow-md ${
                isProcessing || cards.length === 0 
                  ? 'bg-slate-300 cursor-not-allowed shadow-none' 
                  : 'bg-blue-600 hover:bg-blue-700 shadow-blue-300'
              }`}
            >
              {isProcessing ? <Loader2 className="animate-spin" size={18} /> : <Play size={18} />}
              {isProcessing ? 'Processing...' : 'Start Batch'}
            </button>
        </div>
        <input 
          type="file" 
          multiple 
          accept="image/*" 
          ref={fileInputRef} 
          className="hidden" 
          onChange={handleFileSelect}
        />
      </header>

      <div className="flex-1 flex overflow-hidden">
        {/* Main Grid */}
        <div className="flex-1 p-6 overflow-y-auto bg-slate-50">
          {cards.length === 0 ? (
             <div 
               onClick={() => fileInputRef.current?.click()}
               className="h-96 border-2 border-dashed border-slate-300 rounded-xl flex flex-col items-center justify-center text-slate-400 cursor-pointer hover:border-blue-400 hover:bg-blue-50/50 transition-all"
             >
               <Upload size={48} className="mb-4 opacity-50" />
               <p className="text-lg font-medium">Drop card images here</p>
               <p className="text-sm">or click to browse</p>
             </div>
          ) : (
            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6">
              {cards.map(card => (
                <div key={card.id} className="group relative bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden transition-all hover:shadow-md">
                  <div className="aspect-[2.5/3.5] bg-slate-100 relative overflow-hidden">
                    <img 
                      src={card.processedUrl || card.previewUrl} 
                      alt="Card" 
                      className={`w-full h-full object-cover transition-transform duration-500 ${card.status === ProcessingStatus.Processing ? 'scale-105 blur-sm' : ''}`} 
                    />

                    {card.status === ProcessingStatus.Processing && (
                      <div className="absolute inset-0 flex items-center justify-center bg-black/20">
                        <Loader2 className="text-white animate-spin" size={32} />
                      </div>
                    )}

                    {card.status === ProcessingStatus.Completed && (
                       <div className="absolute bottom-2 right-2 bg-green-500 text-white p-1 rounded-full shadow-lg">
                         <Check size={14} />
                       </div>
                    )}

                    <button 
                      onClick={() => removeCard(card.id)}
                      className="absolute top-2 right-2 bg-white/90 p-1.5 rounded-full text-slate-600 opacity-0 group-hover:opacity-100 transition-opacity hover:text-red-500"
                    >
                      <X size={14} />
                    </button>
                  </div>
                  <div className="p-3">
                    <p className="text-xs font-medium text-slate-500 truncate">{card.file.name}</p>
                    <div className="flex justify-between items-center mt-2">
                      <span className={`text-xs px-2 py-0.5 rounded-full font-medium ${
                        card.status === ProcessingStatus.Completed ? 'bg-green-100 text-green-700' :
                        card.status === ProcessingStatus.Processing ? 'bg-blue-100 text-blue-700' :
                        'bg-slate-100 text-slate-600'
                      }`}>
                        {card.status}
                      </span>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Right Settings Panel */}
        <div className="w-80 bg-white border-l border-slate-200 p-6 overflow-y-auto">
          <div className="flex items-center gap-2 mb-6 text-slate-800">
            <Settings size={20} />
            <h3 className="font-bold">Settings</h3>
          </div>

          <div className="space-y-6">
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-2">Aspect Ratio</label>
              <select 
                className="w-full bg-slate-50 border border-slate-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                value={settings.aspectRatio}
                onChange={(e) => setSettings({...settings, aspectRatio: Number(e.target.value)})}
              >
                <option value={2.5/3.5}>Trading Card (2.5 : 3.5)</option>
                <option value={1}>Square (1 : 1)</option>
              </select>
            </div>

            <div className="space-y-3">
              <label className="flex items-center gap-3 p-3 border border-slate-200 rounded-lg cursor-pointer hover:bg-slate-50 transition-colors">
                <input 
                  type="checkbox" 
                  checked={settings.enableUpscaling}
                  onChange={(e) => setSettings({...settings, enableUpscaling: e.target.checked})}
                  className="w-4 h-4 text-blue-600 rounded focus:ring-blue-500"
                />
                <div>
                  <span className="block text-sm font-medium text-slate-900">AI Upscaling</span>
                  <span className="block text-xs text-slate-500">Enhance resolution up to 4x</span>
                </div>
              </label>

              <label className="flex items-center gap-3 p-3 border border-slate-200 rounded-lg cursor-pointer hover:bg-slate-50 transition-colors">
                <input 
                  type="checkbox" 
                  checked={settings.enableDescratching}
                  onChange={(e) => setSettings({...settings, enableDescratching: e.target.checked})}
                  className="w-4 h-4 text-blue-600 rounded focus:ring-blue-500"
                />
                <div>
                  <span className="block text-sm font-medium text-slate-900">Descratching</span>
                  <span className="block text-xs text-slate-500">Remove surface marks</span>
                </div>
              </label>
            </div>

            <div className="pt-6 border-t border-slate-200">
               <div className="mb-2 flex justify-between text-sm">
                 <span className="text-slate-600">Batch Progress</span>
                 <span className="font-medium text-slate-900">{Math.round(progress)}%</span>
               </div>
               <div className="h-2 bg-slate-100 rounded-full overflow-hidden">
                 <div 
                    className="h-full bg-blue-600 transition-all duration-300"
                    style={{ width: `${progress}%` }}
                 ></div>
               </div>
            </div>

            <button 
              onClick={handleDownloadBatch}
              disabled={completedCount === 0 || isDownloading}
              className={`w-full mt-4 flex items-center justify-center gap-2 text-sm font-medium transition-colors ${
                completedCount > 0 && !isDownloading
                  ? 'text-blue-600 hover:text-blue-700 hover:bg-blue-50 py-2 rounded-lg' 
                  : 'text-slate-400 cursor-not-allowed'
              }`}
            >
                {isDownloading ? <Loader2 size={16} className="animate-spin" /> : <Download size={16} />}
                {isDownloading ? 'Zipping...' : `Download All Processed (${completedCount})`}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default BatchCropper;

