                    />
                    <div>
                    <span className="block text-xs font-bold text-gray-200 flex items-center gap-2"><Zap size={12} className="text-[#e0752d]"/> Neural Upscale (4x)</span>
                    <span className="block text-[10px] text-gray-500 mt-1">Super-resolution enhancement</span>
                    </div>
                 </label>
              </div>

               {/* Descratch Controls */}
              <div className="bg-[#181b1f] p-3 border border-[#2c3235] rounded-sm">
                 <label className="flex items-center gap-3 cursor-pointer mb-3">
                    <input 
                    type="checkbox" 
                    checked={settings.enableDescratching}
                    onChange={(e) => setSettings({...settings, enableDescratching: e.target.checked})}
                    className="w-4 h-4 accent-[#3274d9] bg-[#0b0c0e] border-[#2c3235] rounded-sm"
                    />
                    <div>
                    <span className="block text-xs font-bold text-gray-200 flex items-center gap-2"><Layers size={12} className="text-[#3274d9]"/> Smart Descratch</span>
                    </div>
                 </label>

                 <div className={`transition-opacity ${settings.enableDescratching ? 'opacity-100' : 'opacity-30 pointer-events-none'}`}>
                    <div className="flex justify-between text-[10px] text-gray-500 mb-1 font-mono">
                        <span>INTENSITY</span>
                        <span>{Math.round(settings.descratchStrength * 100)}%</span>
                    </div>
                    <input 
                        type="range" 
                        min="0" 
                        max="1" 
                        step="0.1"
                        value={settings.descratchStrength}
                        onChange={(e) => setSettings({...settings, descratchStrength: parseFloat(e.target.value)})}
                        className="w-full h-1 bg-[#2c3235] rounded-lg appearance-none cursor-pointer accent-[#3274d9]"
                    />
                 </div>
              </div>
            </div>

            {/* Terminal / Logs */}
            <div className="flex-1 flex flex-col min-h-[150px]">
                <label className="block text-[10px] font-bold text-gray-500 uppercase tracking-wider mb-2">System Logs</label>
                <div className="flex-1 bg-[#000000] border border-[#2c3235] p-2 font-mono text-[10px] text-gray-400 overflow-y-auto max-h-[200px] rounded-sm">
                    {logs.length === 0 && <span className="opacity-30">Waiting for tasks...</span>}
                    {logs.map((log, i) => (
                        <div key={i} className="mb-0.5 whitespace-nowrap">{log}</div>
                    ))}
                    <div ref={logsEndRef}></div>
                </div>
            </div>

            <div className="pt-4 border-t border-[#2c3235]">
               <div className="mb-2 flex justify-between text-[10px] font-mono text-gray-400">
                 <span>BATCH_PROGRESS</span>
                 <span>{Math.round(progress)}%</span>
               </div>
               <div className="h-1 bg-[#2c3235] rounded-full overflow-hidden mb-4">
                 <div 
                    className="h-full bg-[#3274d9] transition-all duration-300"
                    style={{ width: `${progress}%` }}
                 ></div>
               </div>

               <button 
                  onClick={handleDownloadBatch}
                  disabled={completedCount === 0 || isDownloading}
                  className={`w-full flex items-center justify-center gap-2 text-xs font-bold uppercase tracking-wider py-2.5 rounded-sm transition-colors ${
                    completedCount > 0 && !isDownloading
                      ? 'bg-[#2c3235] hover:bg-[#3274d9] text-white' 
                      : 'bg-[#181b1f] text-gray-600 cursor-not-allowed border border-[#2c3235]'
                  }`}
                >
                    {isDownloading ? <Loader2 size={14} className="animate-spin" /> : <Download size={14} />}
                    {isDownloading ? 'COMPRESSING...' : `DOWNLOAD ARCHIVE`}
                </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

