import { GoogleGenAI, GenerateContentResponse, Type } from "@google/genai";
import { ImageSize, ProcessingSettings } from "../types";

// Helper to get the AI client. 
// For Pro Image/Veo models, we must ensure we use the selected key if available.
const getClient = async (useUserSelectedKey: boolean = false) => {
  if (useUserSelectedKey) {
    if (window.aistudio && await window.aistudio.hasSelectedApiKey()) {
       // Key is injected via environment or handled by the internal proxy if using AI Studio
    }
  }
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

const fileToBase64 = async (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => {
      const result = reader.result as string;
      const base64 = result.split(',')[1];
      resolve(base64);
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

export const generateBotResponse = async (history: { role: string; parts: { text: string }[] }[], newMessage: string): Promise<string> => {
  try {
    const ai = await getClient();
    const chat = ai.chats.create({
      model: 'gemini-3-pro-preview',
      history: history,
      config: {
        systemInstruction: "You are a helpful assistant for a Sports Card Processing application. You know about baseball cards, grading, condition, and image processing.",
      }
    });

    const result = await chat.sendMessage({ message: newMessage });
    return result.text || "I couldn't generate a response.";
  } catch (error) {
    console.error("Chat Error:", error);
    throw error;
  }
};

export const generateCardImage = async (prompt: string, size: ImageSize): Promise<string> => {
  try {
    // Ensure user has selected a key for high-quality generation
    if (window.aistudio) {
        const hasKey = await window.aistudio.hasSelectedApiKey();
        if (!hasKey) {
            await window.aistudio.openSelectKey();
        }
    }

    const ai = await getClient(true);

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview',
      contents: {
        parts: [{ text: prompt }]
      },
      config: {
        imageConfig: {
          imageSize: size,
          aspectRatio: "3:4" // Typical card ratio
        }
      }
    });

    // Iterate to find image part
    if (response.candidates && response.candidates[0].content.parts) {
      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) {
           return `data:image/png;base64,${part.inlineData.data}`;
        }
      }
    }

    throw new Error("No image data received from the model.");
  } catch (error) {
    console.error("Image Generation Error:", error);
    throw error;
  }
};

export const analyzeCardDamage = async (file: File): Promise<{damageScore: number, issues: string[], recommendedFixes: string[]}> => {
    // Force key check for analysis to prevent auth errors
    const ai = await getClient(true);
    const base64 = await fileToBase64(file);

    const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: {
            parts: [
                { inlineData: { mimeType: file.type, data: base64 } },
                { text: `Analyze this sports card image for condition and damage. 
                  Identify: Scratches, Dust, Corner Wear, Centering, and Surface Artifacts.
                  Provide a damage score from 0 (destroyed) to 100 (gem mint).
                  Return JSON.` }
            ]
        },
        config: {
            responseMimeType: "application/json",
            responseSchema: {
                type: Type.OBJECT,
                properties: {
                    damageScore: { type: Type.NUMBER, description: "Score from 0 to 100 representing condition" },
                    issues: { type: Type.ARRAY, items: { type: Type.STRING }, description: "List of specific defects found" },
                    recommendedFixes: { type: Type.ARRAY, items: { type: Type.STRING }, description: "AI restoration steps to apply" }
                }
            }
        }
    });

    if (response.text) {
        return JSON.parse(response.text);
    }
    return { damageScore: 0, issues: ["Analysis failed"], recommendedFixes: [] };
};

export const restoreCard = async (file: File, settings: ProcessingSettings): Promise<string> => {
    // Force key check for restoration
    const ai = await getClient(true);
    const base64 = await fileToBase64(file);

    let prompt = "Restoration task: Return a restored version of this sports card image.";

    if (settings.enableDescratching) {
        prompt += ` Remove all scratches, dust, and surface scuffs. (Intensity: ${settings.descratchStrength}).`;
    }
    if (settings.enableUpscaling) {
        prompt += ` Upscale the image, sharpen details and text. Enhance resolution.`;
    }

    prompt += " IMPORTANT: Preserve the original player likeness, text, logos, and card design EXACTLY. Do not hallucinate new elements. Only clean the surface damage.";

    const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash-image',
        contents: {
            parts: [
                { inlineData: { mimeType: file.type, data: base64 } },
                { text: prompt }
            ]
        }
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) {
            return `data:image/png;base64,${part.inlineData.data}`;
        }
    }
    throw new Error("Restoration failed: No image returned from model.");
};

import React, { useState, useRef, useEffect } from 'react';
import { Upload, X, Check, Loader2, Download, Settings, Play, Trash2, Cpu, Activity, Zap, Layers, Key } from 'lucide-react';
import { CardImage, ProcessingStatus, ProcessingSettings } from '../types';
import { analyzeCardDamage, restoreCard } from '../services/geminiService';
import JSZip from 'jszip';

const BatchCropper: React.FC = () => {
  const [cards, setCards] = useState<CardImage[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isDownloading, setIsDownloading] = useState(false);
  const [logs, setLogs] = useState<string[]>([]);
  const [settings, setSettings] = useState<ProcessingSettings>({
    aspectRatio: 2.5 / 3.5,
    jpegQuality: 95,
    enableUpscaling: true,
    enableDescratching: true,
    descratchStrength: 0.7,
    upscalingScale: 4,
    backgroundColor: 'White'
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const logsEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    logsEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [logs]);

  const addLog = (message: string) => {
    const timestamp = new Date().toISOString().split('T')[1].split('.')[0];
    setLogs(prev => [...prev, `[${timestamp}] ${message}`]);
  };

  const handleFileSelect = (event: React.ChangeEvent<HTMLInputElement>) => {
    if (event.target.files) {
      const newCards: CardImage[] = Array.from(event.target.files).map(file => ({
        id: Math.random().toString(36).substr(2, 9),
        file,
        previewUrl: URL.createObjectURL(file),
        status: ProcessingStatus.Pending,
        originalWidth: 0,
        originalHeight: 0
      }));
      setCards(prev => [...prev, ...newCards]);
      addLog(`Loaded ${newCards.length} new files into buffer.`);
    }
  };

  const removeCard = (id: string) => {
    setCards(prev => prev.filter(c => c.id !== id));
  };

  const handleClearBatch = () => {
    if (window.confirm("Are you sure you want to clear all images?")) {
        setCards([]);
        setLogs([]);
        addLog("Batch buffer cleared.");
    }
  };

  const handleApiKeyUpdate = async () => {
    try {
        if (window.aistudio) {
            await window.aistudio.openSelectKey();
            addLog("System: API Key selection dialog opened.");
        } else {
            addLog("System: Env does not support manual key selection.");
        }
    } catch (e) {
        addLog("Error opening key selector.");
    }
  };

  const processBatch = async () => {
    setIsProcessing(true);
    addLog(`INITIATING BATCH PROCESS - ${cards.length} items`);
    addLog(`CONFIG: Upscale=${settings.enableUpscaling}, Descratch=${settings.enableDescratching} (Str: ${settings.descratchStrength})`);

    for (const card of cards) {
      if (card.status === ProcessingStatus.Completed) continue;

      setCards(prev => prev.map(c => c.id === card.id ? { ...c, status: ProcessingStatus.Processing } : c));
      addLog(`Processing [${card.id}]: ${card.file.name}`);

      try {
          // 1. Analyze Damage
          addLog(`> [${card.id}] Scanning surface artifacts (Gemini Vision)...`);
          const analysis = await analyzeCardDamage(card.file);

          addLog(`> [${card.id}] Condition Score: ${analysis.damageScore}/100`);
          if (analysis.issues.length > 0) {
              addLog(`> [${card.id}] Defects: ${analysis.issues.slice(0, 2).join(", ")}...`);
          }

          // 2. Restore Image
          if (settings.enableDescratching || settings.enableUpscaling) {
             addLog(`> [${card.id}] Applying AI restoration pipeline...`);
             const restoredImageUrl = await restoreCard(card.file, settings);

             setCards(prev => prev.map(c => 
                c.id === card.id ? { ...c, status: ProcessingStatus.Completed, processedUrl: restoredImageUrl } : c
             ));
             addLog(`SUCCESS [${card.id}] Restoration complete.`);
          } else {
             // Just pass through if no AI features enabled (or simple crop in future)
             setCards(prev => prev.map(c => 
                c.id === card.id ? { ...c, status: ProcessingStatus.Completed, processedUrl: c.previewUrl } : c
             ));
             addLog(`SUCCESS [${card.id}] Skipped AI processing.`);
          }

      } catch (error: any) {
          console.error(error);
          addLog(`ERROR [${card.id}] ${error.message || 'Processing failed'}`);
          if (error.message?.includes('401') || error.message?.includes('API keys')) {
             addLog(`SYSTEM ALERT: Authentication failed. Please update your API Key.`);
          }
          setCards(prev => prev.map(c => 
             c.id === card.id ? { ...c, status: ProcessingStatus.Failed } : c
          ));
      }
    }

    addLog("BATCH PROCESS COMPLETE");
    setIsProcessing(false);
  };

  const handleDownloadBatch = async () => {
    const completedCards = cards.filter(c => c.status === ProcessingStatus.Completed && c.processedUrl);
    if (completedCards.length === 0) return;
    setIsDownloading(true);
    addLog("Archiving processed files...");

    try {
      const zip = new JSZip();
      const promises = completedCards.map(async (card) => {
        if (card.processedUrl) {
          try {
            const response = await fetch(card.processedUrl);
            const blob = await response.blob();
            zip.file(`restored-${card.file.name}`, blob);
          } catch (err) {
            console.error(err);
          }
        }
      });

      await Promise.all(promises);
      const content = await zip.generateAsync({ type: "blob" });
      const downloadUrl = URL.createObjectURL(content);
      const link = document.createElement('a');
      link.href = downloadUrl;
      link.download = `cardcrop-batch-${new Date().getTime()}.zip`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(downloadUrl);
      addLog("Download started.");
    } catch (e) {
      addLog("ERROR: Zip generation failed.");
    } finally {
      setIsDownloading(false);
    }
  };

  const completedCount = cards.filter(c => c.status === ProcessingStatus.Completed).length;
  const progress = cards.length > 0 ? (completedCount / cards.length) * 100 : 0;

  // Dashboard Metrics
  const queueLength = cards.filter(c => c.status === ProcessingStatus.Pending).length;
  const processingTime = isProcessing ? "~8.5s" : "0s";

  return (
    <div className="h-full flex flex-col bg-[#0b0c0e] text-gray-300">
      {/* Top Bar / Stats */}
      <div className="h-16 border-b border-[#2c3235] bg-[#111217] flex items-center px-6 justify-between shrink-0">
        <div className="flex items-center gap-6">
            <h2 className="text-xl font-bold text-gray-100 tracking-tight">BATCH OPERATIONS</h2>
            <div className="h-6 w-px bg-[#2c3235]"></div>
            <div className="flex gap-4 text-xs font-mono">
                <div className="flex flex-col">
                    <span className="text-gray-500">QUEUE</span>
                    <span className="text-[#3274d9] font-bold">{queueLength} ITEMS</span>
                </div>
                <div className="flex flex-col">
                    <span className="text-gray-500">COMPLETED</span>
                    <span className="text-[#73bf69] font-bold">{completedCount}</span>
                </div>
                <div className="flex flex-col">
                    <span className="text-gray-500">LATENCY</span>
                    <span className="text-[#e0752d] font-bold">{processingTime}</span>
                </div>
            </div>
        </div>

        <div className="flex gap-3">
             <button 
              onClick={handleClearBatch}
              disabled={cards.length === 0}
              className="px-4 py-2 border border-[#2c3235] hover:bg-[#2c3235] text-gray-400 hover:text-red-400 rounded-sm text-xs font-bold uppercase tracking-wider transition-colors flex items-center gap-2"
            >
              <Trash2 size={14} /> Clear
            </button>
            <button 
              onClick={() => fileInputRef.current?.click()}
              className="px-4 py-2 bg-[#2c3235] hover:bg-[#3c4245] text-gray-100 rounded-sm text-xs font-bold uppercase tracking-wider transition-colors flex items-center gap-2"
            >
              <Upload size={14} /> Add Source
            </button>
            <button 
              onClick={processBatch}
              disabled={isProcessing || cards.length === 0}
              className={`px-6 py-2 rounded-sm text-white text-xs font-bold uppercase tracking-wider flex items-center gap-2 transition-all ${
                isProcessing || cards.length === 0 
                  ? 'bg-[#181b1f] text-gray-600 cursor-not-allowed border border-[#2c3235]' 
                  : 'bg-[#3274d9] hover:bg-[#3274d9]/90 shadow-lg shadow-blue-900/20'
              }`}
            >
              {isProcessing ? <Loader2 className="animate-spin" size={14} /> : <Play size={14} />}
              {isProcessing ? 'Running...' : 'Execute'}
            </button>
        </div>
        <input type="file" multiple accept="image/*" ref={fileInputRef} className="hidden" onChange={handleFileSelect}/>
      </div>

      <div className="flex-1 flex overflow-hidden">
        {/* Main Grid */}
        <div className="flex-1 p-4 overflow-y-auto bg-[#0b0c0e]">
          {cards.length === 0 ? (
             <div 
               onClick={() => fileInputRef.current?.click()}
               className="h-full border border-dashed border-[#2c3235] bg-[#111217]/50 rounded-sm flex flex-col items-center justify-center text-gray-500 cursor-pointer hover:border-[#3274d9] hover:text-[#3274d9] transition-all"
             >
               <Activity size={48} className="mb-4 opacity-20" />
               <p className="font-mono text-lg">NO DATA SOURCE</p>
               <p className="text-xs mt-2 opacity-50">Click to load input buffers</p>
             </div>
          ) : (
            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
              {cards.map(card => (
                <div key={card.id} className="group relative bg-[#181b1f] border border-[#2c3235] rounded-sm overflow-hidden hover:border-[#3274d9] transition-all">
                  {/* Status Indicator Bar */}
                  <div className={`h-1 w-full ${
                      card.status === ProcessingStatus.Completed ? 'bg-[#73bf69]' :
                      card.status === ProcessingStatus.Processing ? 'bg-[#3274d9] animate-pulse' :
                      card.status === ProcessingStatus.Failed ? 'bg-red-500' :
                      'bg-[#2c3235]'
                  }`}></div>

                  <div className="aspect-[2.5/3.5] relative bg-[#000000] p-2">
                    <img 
                      src={card.processedUrl || card.previewUrl} 
                      alt="Card" 
                      className={`w-full h-full object-contain transition-all duration-300 ${card.status === ProcessingStatus.Processing ? 'opacity-50' : ''}`} 
                    />

                    {/* Simulated Scanner Line */}
                    {card.status === ProcessingStatus.Processing && settings.enableDescratching && (
                        <div className="absolute inset-0 border-t-2 border-[#e0752d] opacity-70 animate-[scan_1.5s_ease-in-out_infinite] pointer-events-none bg-gradient-to-b from-[#e0752d]/10 to-transparent h-16 w-full"></div>
                    )}

                    {card.status === ProcessingStatus.Processing && (
                      <div className="absolute inset-0 flex items-center justify-center">
                        <Loader2 className="text-[#3274d9] animate-spin" size={32} />
                      </div>
                    )}

                    <button 
                      onClick={() => removeCard(card.id)}
                      className="absolute top-2 right-2 bg-[#000000]/80 p-1.5 rounded-sm text-gray-400 opacity-0 group-hover:opacity-100 transition-opacity hover:text-red-400 hover:bg-[#000000]"
                    >
                      <X size={14} />
                    </button>
                  </div>

                  <div className="p-3 border-t border-[#2c3235] bg-[#111217]">
                    <div className="flex justify-between items-center">
                        <span className="font-mono text-xs text-gray-400 truncate max-w-[100px]">{card.file.name}</span>
                        <span className={`text-[10px] px-1.5 py-0.5 rounded-sm font-bold uppercase ${
                            card.status === ProcessingStatus.Completed ? 'bg-[#73bf69]/10 text-[#73bf69]' :
                            card.status === ProcessingStatus.Processing ? 'bg-[#3274d9]/10 text-[#3274d9]' :
                            card.status === ProcessingStatus.Failed ? 'bg-red-900/20 text-red-500' :
                            'bg-[#2c3235] text-gray-500'
                        }`}>
                            {card.status === ProcessingStatus.Completed ? 'OK' : card.status}
                        </span>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Right Settings Panel */}
        <div className="w-80 bg-[#111217] border-l border-[#2c3235] flex flex-col">
          <div className="p-4 border-b border-[#2c3235] flex items-center gap-2">
            <Settings size={16} className="text-gray-400" />
            <h3 className="font-bold text-sm tracking-wide text-gray-200">CONFIGURATION</h3>
          </div>

          <div className="p-4 space-y-6 overflow-y-auto flex-1">
            <div>
              <label className="block text-[10px] font-bold text-gray-500 uppercase tracking-wider mb-2">Target Ratio</label>
              <select 
                className="w-full bg-[#0b0c0e] border border-[#2c3235] rounded-sm px-3 py-2 text-xs text-gray-200 focus:border-[#3274d9] outline-none"
                value={settings.aspectRatio}
                onChange={(e) => setSettings({...settings, aspectRatio: Number(e.target.value)})}
              >
                <option value={2.5/3.5}>TRADING CARD (2.5:3.5)</option>
                <option value={1}>SQUARE (1:1)</option>
              </select>
            </div>

            <div className="space-y-4">
