import { GoogleGenAI, Type } from "@google/genai";
import { ImageSize, ProcessingSettings, AnalysisResult, RestorationLevel } from "../types";

// Helper to get the AI client. 
const getClient = async (useUserSelectedKey: boolean = false) => {
  if (useUserSelectedKey) {
    if (window.aistudio && await window.aistudio.hasSelectedApiKey()) {
       // Key handled by proxy
    }
  }
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

const fileToBase64 = async (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => {
      const result = reader.result as string;
      const base64 = result.split(',')[1];
      resolve(base64);
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

// Client-side cropping using Canvas based on AI bounding box
export const cropImage = async (file: File, box: number[]): Promise<string> => {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => {
      const canvas = document.createElement('canvas');
      const [ymin, xmin, ymax, xmax] = box;

      // Calculate pixel coordinates
      const x = xmin * img.width;
      const y = ymin * img.height;
      const width = (xmax - xmin) * img.width;
      const height = (ymax - ymin) * img.height;

      // Add a small padding (1%)
      const padding = 0; // width * 0.01;

      canvas.width = width + (padding * 2);
      canvas.height = height + (padding * 2);
      const ctx = canvas.getContext('2d');

      if (!ctx) {
        reject(new Error("Could not get canvas context"));
        return;
      }

      // Draw cropped area
      ctx.drawImage(img, x, y, width, height, 0, 0, canvas.width, canvas.height);
      resolve(canvas.toDataURL('image/jpeg', 0.95));
    };
    img.onerror = reject;
    img.src = URL.createObjectURL(file);
  });
};

export const generateBotResponse = async (history: { role: string; parts: { text: string }[] }[], newMessage: string): Promise<string> => {
  try {
    const ai = await getClient();
    const chat = ai.chats.create({
      model: 'gemini-3-pro-preview',
      history: history,
      config: {
        systemInstruction: "You are 'Lumina', an advanced AI assistant for Sports Card restoration. You are concise, professional, and knowledgeable about card grading (PSA/BGS), surface damage, and value.",
      }
    });

    const result = await chat.sendMessage({ message: newMessage });
    return result.text || "I couldn't generate a response.";
  } catch (error) {
    console.error("Chat Error:", error);
    throw error;
  }
};

export const generateCardImage = async (prompt: string, size: ImageSize): Promise<string> => {
  try {
    if (window.aistudio) {
        const hasKey = await window.aistudio.hasSelectedApiKey();
        if (!hasKey) {
            await window.aistudio.openSelectKey();
        }
    }

    const ai = await getClient(true);
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview',
      contents: { parts: [{ text: prompt }] },
      config: {
        imageConfig: { imageSize: size, aspectRatio: "3:4" }
      }
    });

    if (response.candidates && response.candidates[0].content.parts) {
      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) {
           return `data:image/png;base64,${part.inlineData.data}`;
        }
      }
    }
    throw new Error("No image data received from the model.");
  } catch (error) {
    console.error("Image Generation Error:", error);
    throw error;
  }
};

export const analyzeCardDamage = async (file: File): Promise<AnalysisResult> => {
    const ai = await getClient(true);
    const base64 = await fileToBase64(file);

    const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: {
            parts: [
                { inlineData: { mimeType: file.type, data: base64 } },
                { text: `Analyze this sports card image.
                  1. Detect the bounding box of the card exactly [ymin, xmin, ymax, xmax] (0-100 scale normalized to 0-1).
                  2. Identify condition issues (Scratches, Dust, Corner Wear, Centering).
                  3. Provide a damage score (0-100).
                  Return JSON.` }
            ]
        },
        config: {
            responseMimeType: "application/json",
            responseSchema: {
                type: Type.OBJECT,
                properties: {
                    damageScore: { type: Type.NUMBER },
                    issues: { type: Type.ARRAY, items: { type: Type.STRING } },
                    recommendedFixes: { type: Type.ARRAY, items: { type: Type.STRING } },
                    boundingBox: { type: Type.ARRAY, items: { type: Type.NUMBER }, description: "ymin, xmin, ymax, xmax" }
                }
            }
        }
    });

    if (response.text) {
        return JSON.parse(response.text);
    }
    return { damageScore: 0, issues: ["Analysis failed"], recommendedFixes: [], boundingBox: [0,0,1,1] };
};

export const restoreCard = async (file: File, settings: ProcessingSettings, analysis?: AnalysisResult): Promise<string> => {
    const ai = await getClient(true);

    // If auto-crop is enabled and we have coordinates, crop locally first
    let base64Image = '';

    if (settings.autoCrop && analysis?.boundingBox) {
       const croppedDataUrl = await cropImage(file, analysis.boundingBox);
       base64Image = croppedDataUrl.split(',')[1];
    } else {
       base64Image = await fileToBase64(file);
    }

    // Build Prompt based on Strength Levels
    let strengthPrompt = "";
    switch (settings.restorationLevel) {
      case RestorationLevel.Light:
        strengthPrompt = "Perform a conservative restoration. Only remove obvious dust. Do not alter texture.";
        break;
      case RestorationLevel.Balanced:
        strengthPrompt = "Balance restoration. Remove scratches and dust. Sharpen text slightly. Keep paper grain visible.";
        break;
      case RestorationLevel.Aggressive:
        strengthPrompt = "Heavy restoration. Completely remove all scratches, creases and surface wear. Reconstruct damaged corners. Aggressive denoise and sharpening.";
        break;
    }

    let prompt = `Task: Sports Card Restoration.
    ${strengthPrompt}
    ${settings.enableUpscaling ? "Upscale the image resolution and enhance clarity." : ""}
    Input Context: The card has ${analysis?.issues.join(", ")}.
    Constraint: Preserve player face, team logos, and text PERFECTLY. Output as a clean, high-quality scan.`;

    const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash-image',
        contents: {
            parts: [
                { inlineData: { mimeType: "image/jpeg", data: base64Image } },
                { text: prompt }
            ]
        }
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) {
            return `data:image/png;base64,${part.inlineData.data}`;
        }
    }
    throw new Error("Restoration failed: No image returned from model.");
};

